FKE_st.name='FKE'; 
FKE_st.lat=32.75 ;
FKE_st.lon=128.68;
FKE_st.alt=75;
FKE_st.env='coast';
FKE_st.footp='RB';
%%

%reading from matlab tool
FKE_rd=table2timetable(bc_200904_202603_cosmos_maap_unified_r_to_Martine);
FKE_rd.BaR_A=FKE_rd.unifiedBC_STPMicrogramsM___3_.*10.3;
FKE_rd.BaR_Amaap=FKE_rd.maap_BC_microgramsM___3Using10_3M2_g_CorrectedToSTP_.*10.3;
FKE_rd.Properties.DimensionNames{1}='Time';
names_rd=fieldnames(FKE_rd);


%%
datevec(FKE_rd.Time(1)) % begin in 2016 %[output:316366d9]
datevec(FKE_rd.Time(end)) % end in 2025 %[output:867a923d]
%prctile(FKE_rd.U370_S,[5 50 95]) % < 30%, ok. 

plotFigControl(FKE_rd,FKE_st.name); %[output:11c76eff] %[output:16f93707] %[output:35d9f761] %[output:5ddc1eba] %[output:5ce40bd8] %[output:67f96fc5] %[output:73ebfabf] %[output:0207d697]
% WAIT FOR DATA, REST NO OK.
%%
% BP detection for abs
names_abs={'BaR_A'};
break_FKE_abs_BP=change_point_analysis_Def(FKE_rd,names_abs,0.05,'FKE','Absorption'); %[output:8060cbed] %[output:30c44ff4]
T_FKE_abs_BP=make_table_breakpoints_def(break_FKE_abs_BP);

%%

%%


%%
FKE_tr=FKE_rd;
FKE_tr.y=year(FKE_tr.Time);
% begin at the beginning of a year: 2016 
%end: 2025
P=timerange('2010-01-01','2025-01-01');
FKE_tr=FKE_tr(P,:);

names=fieldnames(FKE_tr);
c=startsWith(names,["cosm","std","maap","unif"]) ;
N=names(c);
for i=1:length(N)
    FKE_tr.(N{i})=[];
end

%%
[FKE_result_MK,FKE_result_LMSlog,FKE_result_LMSlin]=all_trend_STN(FKE_tr,FKE_st); %[output:65e5c2fb] %[output:8d06bf93] %[output:30bcce4b] %[output:609e7d26] %[output:113781d0] %[output:3e7f7c7f] %[output:43e82b14] %[output:08d74c69] %[output:1958405f] %[output:491cc4b1] %[output:87b61b6f] %[output:557ea8f1] %[output:02d76d21] %[output:37d2a8a4] %[output:99ff9d55] %[output:3c0f05f9] %[output:10ff1aab] %[output:6d7c393d] %[output:0d88a39b] %[output:50ecdb06] %[output:31b5c9a5] %[output:97e9a03f] %[output:97ec73ea] %[output:02ea25bf] %[output:47d48a82]

writetable(FKE_result_MK,'FKE_res_MK.txt'); %, 'delimiter',',' )
writetable(FKE_result_LMSlog,'FKE_res_LMSlog.txt'); 
writetable(FKE_result_LMSlin,'FKE_res_LMSlin.txt'); 
plot_10y_in_two(FKE_result_MK, FKE_st,'y'); %[output:87d92555] %[output:8a0d3525]
%%
 timetable_to_netcdf(FKE_tr,'FKE_tr_def.nc'); %[output:504a06e4]

